export async function loadProfile(token: string) {
  return fetch("http://backend.test/api/profile", {
    headers: {
      "X-Access-Token": token,
    },
  })
}

export function authenticate(headers: Record<string, string | undefined>) {
  const auth = headers["authorization"]
  if (!auth?.startsWith("Bearer ")) {
    return { ok: false as const, status: 401, reason: "missing bearer token" }
  }
  return { ok: true as const, token: auth.slice("Bearer ".length) }
}

import { authenticate } from "./auth"

export function profile(headers: Record<string, string | undefined>) {
  const result = authenticate(headers)
  if (!result.ok) return { status: result.status, body: { error: result.reason } }
  return { status: 200, body: { id: "user-1" } }
}
